        "question": "Plastiklerin geri dönüşümü genellikle fiziksel bir işlemdir: Toplanır, yıkanır, eritilir ve yeni kalıplara dökülür.\nAşağıda verilen polimerlerden hangisinin bu yolla (eritilip tekrar kalıplanarak) **geri dönüştürülmesi çok zordur veya imkânsızdır?** (Çünkü ısıtıldığında erimez, parçalanır).",
