        "question": "Otomobil lastikleri, ayakkabı tabanları, silgiler ve bazı eldivenlerin temel malzemesi olan **Kauçuk** ile ilgili;\nI. Tropik bölgelerde yetişen kauçuk ağacının özsuyundan (lateks) elde edilen \"Doğal Kauçuk\" formları vardır.\nII. Petrokimya tesislerinde petrolden elde edilen \"Sentetik Kauçuk\" formları vardır.\nIII. Kauçuğun daha dayanıklı ve sert (elastikiyeti kontrollü) hâle gelmesi için kükürt ile ısıtılıp çapraz bağlanması işlemine \"Vulkanizasyon\" denir.\nifadelerinden hangileri doğrudur?",
