        "question": "Cildimizdeki gözenekleri tıkayarak oksijen alışverişini kesen, genellikle petrol rafinasyonundan elde edilen ve ucuz olduğu için dudak kremleri, nemlendiriciler ve merhemlerde bolca kullanılan koyu kıvamlı (yağlımsı) \"yardımcı madde\" aşağıdakilerden hangisidir?",
