        "question": "Temizlik maddeleri üretiminde;\nSodyum karbonat ($Na_2CO_3$) $\\rightarrow$ Çamaşır Sodası\nSodyum hipoklorit ($NaClO$) $\\rightarrow$ Çamaşır Suyu\nSodyum hidroksit ($NaOH$) $\\rightarrow$ Sud Kostik (Lavabo Açıcı)\nYukarıdaki kimyasalların üçünde de ortak olarak bulunan element (veya iyon) aşağıdakilerden hangisidir?",
