        "question": "Sert sularda (kireçli sularda) sabunun köpürmemesi ve tortu bırakması temizliği zorlaştırır.\nÇamaşır yıkarken sert suların bu olumsuz etkisini ortadan kaldırmak (suyu yumuşatmak) için çamaşır makinelerinde veya elde yıkamada suya eklenen **bazik karakterli** tuz aşağıdakilerden hangisidir?\n(Not: Bu madde $Ca^{2+}$ iyonlarını karbonat olarak çöktürür).",
