        "question": "İlaçların ağız (oral), damar (enjeksiyon), solunum (inhalasyon) veya deri (topikal) gibi farklı **uygulama yolları** vardır.\nAşağıdaki hastalıklardan (veya kriz durumlarından) hangisi için, ilacın hastaya **doğrudan damar yoluyla (enjeksiyon/iğne)** verilmesi tıbbi olarak zorunlu ve mantıklıdır?",
