        "question": "Polimer ambalaj atıklarının (plastiklerin) doğaya karışması, parçalanması çok uzun yıllar aldığı için ciddi su ve toprak kirliliğine neden olmaktadır.\nAşağıdaki plastik ürünlerden hangisinin doğada (denizde veya toprakta) tamamen yok olması/çözünmesi, diğerlerine göre **çok daha uzun yüzyıllar (bazen bin yıl)** sürmektedir?",
