        "question": "Temizlik ürünleri ve kişisel bakım malzemelerinin etiketlerini okuyan bir kişi, içerikte **\"Triklosan (Triclosan)\"** maddesini görür.\nÖzellikle \"Antibakteriyel Sabun\" olarak pazarlanan ürünlerde bulunan bu maddenin, günümüzde sağlık otoriteleri (FDA vb.) tarafından kullanımının yasaklanması/sınırlandırılması sürecine girilmesinin **temel nedeni** aşağıdakilerden hangisidir?",
