        "question": "İlaçların üretim süreçlerinde, hastaya verilecek olan \"Etken Madde (Aktif Madde)\"nin miktarı genellikle çok azdır (Örneğin 1 miligram).\nBu kadar küçük bir dozu hastanın eliyle tutup yutması veya kullanması imkânsız olduğu için ilacın hacmini büyütmek, tadını güzelleştirmek, raf ömrünü uzatmak ve kolay yutulmasını sağlamak amacıyla ilaç formülüne katılan \"yardımcı (inaktif) maddeler\"e ne ad verilir?",
