        "question": "Çamaşır ve bulaşık makinelerinde suyu yumuşatmak için kullanılan temizlik tuzu veya \"Kireç Önleyici\" maddeler, suyun sertliğine sebep olan hangi iki elementi tutarak (veya çöktürerek) makineleri kireçlenmeden korurlar?",
