        "correctAnswer": "C",
        "difficulty": "medium",
        "solution": "A kabı saf sudur, sabun çok iyi köpürür. B kabında kalsiyum ($Ca^{2+}$) vardır (sert su), sabunun karboksilat başları kalsiyumla birleşip çözünmeyen bir tuz (sabun taşı/çökelek) oluşturur ve sabun KESİLİR (Köpürmez). C kabında kalsiyum olmasına rağmen Sentetik Deterjan vardır; deterjanın sülfonat (veya sülfat) uçları kalsiyumla çökelmez, dolayısıyla sert suda da köpürür. Bu deneyi tam olarak C seçeneği bilimsel bir şekilde özetlemektedir."
