            "text": "Pamuk lifinin (Selüloz) yapısında bulunan çok sayıdaki hidroksil ($–OH$) gruplarının su molekülleriyle güçlü **Hidrojen Bağları** kurarak suyu/teri (hidrofilik) içine çekebilmesi; Polyesterin (sentetik plastik) yapısında ise suyu sevmeyen (hidrofobik) grupların yoğun olması."
