        "question": "*Sağlık ve Kozmetik Bağlamı:*\nPiyasada \"Organik, %100 Doğal ve Katkısız\" etiketiyle satılan su bazlı (örneğin aloe vera suyu içeren) bir yüz nemlendiricisi krem, kapağı açıldıktan sadece 15 gün sonra yeşillenmeye, üzerinde küf lekeleri oluşmaya ve kötü kokmaya başlamıştır. Aynı markanın markette satılan benzer bir kremi ise 2 yıl boyunca bozulmadan durabilmektedir.\n**Bu iki krem arasındaki bozulma süresi farkı, markette satılan uzun ömürlü kremde aşağıdaki \"Gıda/Kozmetik Katkı Maddesi\" sınıflarından hangisinin kesinlikle bulunduğunu kanıtlar?**",
