            "text": "Sabunun hidrofob (yağı seven/apolar) kuyrukları, virüsün dışındaki Lipit (Yağ) Zarına saplanıp yağı çözer; Hidrofil (suyu seven) başları ise suya tutunur. 20 saniye ovalama sonucunda sabun molekülleri virüsün yağ zarını yırtarak parçalar ve virüsü mekanik olarak imha eder."
